<##
.SYNOPSIS
  Appends a validated Enterprise Skill lifecycle transition without mutating the release.
##>
param([Parameter(Mandatory=$true)][string]$ReleasePath,[Parameter(Mandatory=$true)][ValidateSet('static_checked','isolated_trial','approved','active','suspended','rolled_back','revoked')][string]$ToStatus,[Parameter(Mandatory=$true)][string]$ActorId,[Parameter(Mandatory=$true)][string]$TaskId,[Parameter(Mandatory=$true)][string]$GrantId,[Parameter(Mandatory=$true)][string]$TraceId,[string]$EvidenceRef='',[string]$ApprovedBy='',[string]$IndependentVerifierId='',[string]$RollbackTargetRef='',[switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$root=[IO.Path]::GetFullPath((Join-Path $projectRoot '.qianlima/run-traces/enterprise-skills/releases')).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;$ledger=Join-Path $projectRoot '.qianlima/run-traces/enterprise-skills/lifecycle.jsonl';function Emit([hashtable]$Value,[int]$Code=0){if($PassThru){$Value|ConvertTo-Json -Depth 12}else{$Value|Format-List};if($Code-ne0){exit $Code}};try{$full=(Resolve-Path -LiteralPath $ReleasePath -ErrorAction Stop).Path;$release=Get-Content -LiteralPath $full -Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='skill_release_not_found_or_invalid';transition_written=$false}) 1};if(-not$full.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){Emit ([ordered]@{status='blocked';reason='skill_release_outside_governed_root';transition_written=$false}) 1};$current=[string]$release.status;if(Test-Path -LiteralPath $ledger){foreach($line in @(Get-Content -LiteralPath $ledger -Encoding UTF8)){if($line){try{$e=$line|ConvertFrom-Json;if([string]$e.release_id-eq[string]$release.release_id){$current=[string]$e.to_status}}catch{Emit ([ordered]@{status='blocked';reason='skill_lifecycle_ledger_invalid';transition_written=$false}) 1}}}};$allowed=@{candidate=@('static_checked','revoked');static_checked=@('isolated_trial','revoked');isolated_trial=@('approved','suspended','rolled_back','revoked');approved=@('active','suspended','rolled_back','revoked');active=@('suspended','rolled_back','revoked');suspended=@('isolated_trial','rolled_back','revoked');rolled_back=@('revoked');revoked=@()};if(@($allowed[$current])-notcontains$ToStatus){Emit ([ordered]@{status='blocked';reason='invalid_skill_state_transition';from_status=$current;to_status=$ToStatus;transition_written=$false}) 1};if($ToStatus-in@('static_checked','isolated_trial','approved','active','rolled_back')-and[string]::IsNullOrWhiteSpace($EvidenceRef)){Emit ([ordered]@{status='blocked';reason='skill_transition_evidence_required';transition_written=$false}) 1};if($ToStatus-eq'approved'-and([string]::IsNullOrWhiteSpace($ApprovedBy)-or[string]::IsNullOrWhiteSpace($IndependentVerifierId)-or$ApprovedBy-eq$IndependentVerifierId)){Emit ([ordered]@{status='blocked';reason='distinct_human_approver_and_independent_verifier_required';transition_written=$false}) 1};if($ToStatus-eq'rolled_back'-and[string]::IsNullOrWhiteSpace($RollbackTargetRef)){Emit ([ordered]@{status='blocked';reason='rollback_target_required';transition_written=$false}) 1};$event=[ordered]@{schema_version=1;event_id=[Guid]::NewGuid().ToString('n');release_id=[string]$release.release_id;from_status=$current;to_status=$ToStatus;actor_id=$ActorId;evidence_ref=if($EvidenceRef){$EvidenceRef}else{$null};approved_by=if($ApprovedBy){$ApprovedBy}else{$null};independent_verifier_id=if($IndependentVerifierId){$IndependentVerifierId}else{$null};rollback_target_ref=if($RollbackTargetRef){$RollbackTargetRef}else{$null};created_at=[DateTime]::UtcNow.ToString('o');execution_authority=$false;tool_authority=$false;data_scope_authority=$false};New-Item -ItemType Directory -Path (Split-Path -Parent $ledger) -Force|Out-Null;[IO.File]::AppendAllText($ledger,(($event|ConvertTo-Json -Compress)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));$types=@{isolated_trial='skill_trial_started';approved='skill_approved';active='skill_activated';suspended='skill_suspended';rolled_back='skill_rolled_back';revoked='skill_revoked';static_checked='artifact_received'};$decision=if($ToStatus-in@('suspended')){'pause'}elseif($ToStatus-in@('rolled_back','revoked')){'revoke'}else{'accept'};$audit=Join-Path $PSScriptRoot 'append-enterprise-audit-event.ps1';try{& $audit -EventType $types[$ToStatus] -Decision $decision -TenantId ([string]$release.tenant_id) -OrganizationId ([string]$release.organization_id) -UserId $ActorId -AgentId 'skill-governor' -AgentVersion 'skill-lifecycle-v1' -TaskId $TaskId -GrantId $GrantId -TraceId $TraceId -PolicyVersion '2.14.0' -ArtifactRefs ('skill-release://'+[string]$release.release_id) -EvidenceRefs @($EvidenceRef,$RollbackTargetRef|Where-Object{$_}) -PassThru|Out-Null}catch{Emit ([ordered]@{status='blocked';reason='skill_transition_audit_failed';transition_written=$true;effective_status=$ToStatus}) 1};Emit ([ordered]@{status='transitioned';release_id=[string]$release.release_id;from_status=$current;effective_status=$ToStatus;transition_written=$true;release_mutated=$false;installed=$false;execution_authority=$false;tool_authority=$false;data_scope_authority=$false;external_calls=$false})
